def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (everything after first '-' after core version)
        if '-' in v_without_build:
            # Find the first '-' which separates core from pre-release
            parts = v_without_build.split('-', 1)
            core = parts[0]
            prerelease = parts[1]
        else:
            core = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_parts = core.split('.')
        major = int(version_parts[0])
        minor = int(version_parts[1]) if len(version_parts) > 1 else 0
        patch = int(version_parts[2]) if len(version_parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            identifiers = prerelease.split('.')
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting:
        # 1. Compare major, minor, patch numerically
        # 2. Version with no pre-release sorts after version with pre-release
        #    (so we use a tuple where no prerelease is "greater")
        # 3. Pre-release identifiers are compared as parsed
        # 4. Maintain input order for equal versions (stable sort)

        if prerelease_identifiers:
            # Has pre-release
            return (major, minor, patch, 0, prerelease_identifiers, index)
        else:
            # No pre-release - should sort after same version with pre-release
            return (major, minor, patch, 1, [], index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

